import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { createCampaign } from "@/lib/campaigns";
import { deliverOne } from "@/lib/inngest";
import { readQuotaSnapshot } from "@/lib/quota-usage";
import { markReplied, undoReply } from "@/lib/recipient-actions";
import { GET } from "@/app/api/quota/route";

describe.runIf(databaseTestsEnabled)("authenticated quota reporting", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  it("preserves legacy fields and adds safe lifecycle metadata while gating is off", async () => {
    await setGating(boundary.db, false);
    const f = await usageOwner(boundary.db);
    await createCampaign(f.user.id, await f.input(4));
    boundary.auth.mockResolvedValue({ user: { id: f.user.id } });
    const response = await GET();
    expect(await response.json()).toEqual({
      used: 4,
      limit: 200,
      notices: [],
      accessVersion: expect.any(String),
    });
    expect(response.headers.get("Cache-Control")).toBe("private, no-store");
  });
  it("reports sent/reserved/remaining for both periods and leaves reply marking outside accounting", async () => {
    await setGating(boundary.db, true);
    const f = await usageOwner(boundary.db),
      campaign = await createCampaign(f.user.id, await f.input(2));
    const send = await boundary.db.send.findFirstOrThrow({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
    });
    await deliverOne(f.user.id, send.id);
    const snapshot = await readQuotaSnapshot(f.user.id);
    expect(snapshot).toMatchObject({
      mode: "gated",
      used: 2,
      limit: 3,
      plan: "FREE",
      daily: { sent: 1, reserved: 1, remaining: 1 },
      monthly: { sent: 1, reserved: 1, remaining: 13 },
    });
    boundary.user.mockResolvedValue(f.user);
    expect(await markReplied(send.id)).toMatchObject({
      ok: false,
      code: "UPGRADE_REQUIRED",
    });
    expect(await readQuotaSnapshot(f.user.id)).toEqual(snapshot);
    expect(await undoReply(send.id)).toMatchObject({
      ok: false,
      code: "UPGRADE_REQUIRED",
    });
    expect(await readQuotaSnapshot(f.user.id)).toEqual(snapshot);
    boundary.auth.mockResolvedValue({ user: { id: f.user.id } });
    expect(await (await GET()).json()).toEqual(snapshot);
    boundary.auth.mockResolvedValue(null);
    expect((await GET()).status).toBe(401);
  });
});
